/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_chk_citizen_dob
      BEFORE INSERT ON citizens
      FOR EACH ROW
      BEGIN
        IF NEW.dob > CURRENT_DATE THEN
          SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'Date of birth cannot be in the future.';
        END IF;
      END */;;
