  `origin` varchar(50) DEFAULT 'Global',
  `total_prescribed_count` int(11) DEFAULT 0,
  `manufacturer` varchar(150) DEFAULT 'Essential Drugs Co. Ltd. (EDCL)',
  PRIMARY KEY (`medicine_id`),
  FULLTEXT KEY `ft_medicine` (`brand_name`,`generic_name`),
  FULLTEXT KEY `idx_ft_medicines` (`brand_name`,`generic_name`)
) ENGINE=InnoDB AUTO_INCREMENT=728 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
