INSERT INTO `messages` VALUES (1,'BD-2000-0001','DOC-1001','Good morning Doctor, I have been taking Amlodipine 5mg for 4 days as prescribed, but feel slightly lightheaded around noon. Should I adjust the timing?',1,'2026-08-26 17:01:07'),(2,'DOC-1001','BD-2000-0001','Hello! Mild lightheadedness can happen initially as peripheral vascular resistance drops. Please check your blood pressure at noon and take the tablet right after breakfast with a glass of water.',1,'2026-08-26 17:46:07'),(3,'BD-2000-0001','DOC-1001','Understood Doctor. Should I strictly restrict dietary salt, and are 30-minute morning brisk walks safe?',1,'2026-08-26 18:31:07'),(4,'DOC-1001','BD-2000-0001','Keep sodium under 2g daily. Moderate walks are safe and strongly encouraged. If systolic drops below 100 mmHg, message me immediately.',1,'2026-08-26 19:16:07'),(5,'BD-2000-0001','DOC-1002','Doctor, my fasting blood glucose was 7.8 mmol/L and 2-hour post-meal was 11.2 mmol/L. I am taking Metformin 500mg twice daily.',1,'2026-08-23 17:01:07'),(6,'DOC-1002','BD-2000-0001','Thank you for tracking. Since post-prandial remains above our 8.5 target, ensure you take Metformin with meals and minimize refined carbohydrates in your evening diet.',1,'2026-08-23 17:46:07'),(7,'BD-2000-0001','DOC-1002','Should I schedule an HbA1c and kidney function test before our upcoming clinic review?',1,'2026-08-23 18:31:07'),(8,'DOC-1002','BD-2000-0001','Yes, please complete an HbA1c and serum creatinine test next week, then upload the PDF report directly to your xMED vault.',1,'2026-08-23 19:16:07'),(9,'BD-2000-0001','DOC-1002','Will do Doctor, uploaded last month’s lipid panel as well.',1,'2026-08-23 20:01:07'),(10,'BD-2000-0001','DOC-1003','Hello Doctor, I developed a sudden fever of 102°F yesterday with retro-orbital eye pain and severe body ache. Could this be dengue?',1,'2026-08-20 17:01:07'),(11,'DOC-1003','BD-2000-0001','Given seasonal trends, do NOT take any Ibuprofen or Aspirin. Take only Paracetamol 500mg up to every 6 hours and drink plenty of ORS and coconut water.',1,'2026-08-20 17:46:07'),(12,'BD-2000-0001','DOC-1003','Should I get a Complete Blood Count (CBC) and Dengue NS1 antigen test done today?',1,'2026-08-20 18:31:07'),(13,'DOC-1003','BD-2000-0001','Yes, get a CBC and NS1 antigen test today. If platelets drop below 100,000 or you notice severe abdominal pain, proceed to the hospital emergency triage.',1,'2026-08-20 19:16:07'),(14,'BD-2000-0001','DOC-1004','Dr. Kabir, I have severe burning in my upper chest at night, despite taking Omeprazole 20mg daily.',1,'2026-08-17 17:01:07'),(15,'DOC-1004','BD-2000-0001','Make sure you take Omeprazole 30 minutes before breakfast on an empty stomach. Avoid spicy dinners and do not lie flat within 2 hours of eating.',1,'2026-08-17 17:46:07'),(16,'BD-2000-0001','DOC-1004','Can I take a chewable antacid if nighttime burning wakes me up?',1,'2026-08-17 18:31:07'),(17,'DOC-1004','BD-2000-0001','Yes, an aluminum-magnesium hydroxide chewable antacid can be taken for breakthrough nocturnal acidity.',1,'2026-08-17 19:16:07'),(18,'BD-2000-0001','DOC-1004','Thank you Doctor, adjusting my meal schedule tonight.',1,'2026-08-17 20:01:07'),(19,'DOC-1004','BD-2000-0001','You are welcome. Keep a symptom diary for the next 7 days.',0,'2026-08-17 20:46:07'),(20,'BD-2000-0001','DOC-1005','Doctor, my child has been coughing persistently at night and has a faint wheezing sound during running.',1,'2026-08-14 17:01:07'),(21,'DOC-1005','BD-2000-0001','This suggests reactive airway bronchospasm. Please administer the Salbutamol 100mcg inhaler with a spacer: 2 puffs as directed.',1,'2026-08-14 17:46:07'),(22,'BD-2000-0001','DOC-1005','How frequently can we repeat the inhaler puffs if coughing persists?',1,'2026-08-14 18:31:07'),(23,'DOC-1005','BD-2000-0001','You can repeat 2 puffs after 20 minutes once. If chest indrawing or breathlessness appears, visit our emergency center immediately.',1,'2026-08-14 19:16:07'),(24,'BD-2000-0002','DOC-1004','Hello Doctor, the red itchy rash on my forearms has flared up after using synthetic laundry powder.',1,'2026-08-19 17:02:07'),(25,'DOC-1004','BD-2000-0002','Apply the Hydrocortisone cream thinly twice daily for 5 days only, followed by liberal amounts of plain petroleum jelly.',1,'2026-08-19 17:47:07'),(26,'BD-2000-0002','DOC-1004','Can I take an antihistamine like Cetirizine 10mg at night for the itching?',1,'2026-08-19 18:32:07'),(27,'DOC-1004','BD-2000-0002','Yes, Cetirizine 10mg at bedtime will relieve nighttime itching and help you rest without scratching.',1,'2026-08-19 19:17:07'),(28,'BD-2000-0002','DOC-1005','Good afternoon Doctor, my abdominal surgical incision looks slightly pink, but there is no fever or pus.',1,'2026-08-16 17:02:07'),(29,'DOC-1005','BD-2000-0002','Mild pink erythema is normal during surgical wound remodeling. Keep the area completely dry and clean with sterile dressing.',1,'2026-08-16 17:47:07'),(30,'BD-2000-0002','DOC-1005','When should I visit the outpatient clinic for suture removal?',1,'2026-08-16 18:32:07'),(31,'DOC-1005','BD-2000-0002','Please visit the surgical OPD this Thursday between 9 AM and 1 PM for stitch removal and scar assessment.',1,'2026-08-16 19:17:07'),(32,'BD-2000-0002','DOC-1006','Doctor, my fasting lipid profile shows LDL 155 mg/dL. I have started Atorvastatin 10mg nightly.',1,'2026-08-26 17:02:07'),(33,'DOC-1006','BD-2000-0002','Atorvastatin works best when taken at bedtime to target peak hepatic cholesterol synthesis. Continue taking it nightly.',1,'2026-08-26 17:47:07'),(34,'BD-2000-0002','DOC-1006','Should I be concerned about muscle soreness or liver enzymes?',1,'2026-08-26 18:32:07'),(35,'DOC-1006','BD-2000-0002','Mild fatigue is rare, but report any severe unexplained muscle cramps. We will recheck liver enzymes and lipid levels in 8 weeks.',0,'2026-08-26 19:17:07'),(36,'BD-2000-0002','DOC-1007','Dr. Tanvir, I get throbbing one-sided headaches preceded by bright zigzag lines in my visual field.',1,'2026-08-23 17:02:07'),(37,'DOC-1007','BD-2000-0002','These are classic migraine episodes with aura. Take Naproxen 500mg immediately when the visual aura begins, before the pain peaks.',1,'2026-08-23 17:47:07'),(38,'BD-2000-0002','DOC-1007','Should I avoid specific dietary triggers like aged cheese or caffeine?',1,'2026-08-23 18:32:07'),(39,'DOC-1007','BD-2000-0002','Yes, maintain a regular sleep schedule, stay hydrated, and note down food triggers in your daily health journal.',1,'2026-08-23 19:17:07'),(40,'BD-2000-0002','DOC-1008','Doctor, my TSH is 5.8 mIU/L on Levothyroxine 50mcg. I still feel unusually cold and sluggish in the morning.',1,'2026-08-20 17:02:07'),(41,'DOC-1008','BD-2000-0002','Your dose requires a slight adjustment. Increase Levothyroxine to 75mcg daily, taken with plain water 45 minutes before breakfast.',1,'2026-08-20 17:47:07'),(42,'BD-2000-0002','DOC-1008','Can I take my calcium and vitamin D tablets together with the thyroid pill?',1,'2026-08-20 18:32:07'),(43,'DOC-1008','BD-2000-0002','No, calcium binds to thyroxine and blocks absorption. Separate calcium supplements by at least 4 hours.',1,'2026-08-20 19:17:07'),(44,'BD-2000-0003','DOC-1007','Good morning Doctor, I have been taking Amlodipine 5mg for 4 days as prescribed, but feel slightly lightheaded around noon. Should I adjust the timing?',1,'2026-08-25 17:03:07'),(45,'DOC-1007','BD-2000-0003','Hello! Mild lightheadedness can happen initially as peripheral vascular resistance drops. Please check your blood pressure at noon and take the tablet right after breakfast with a glass of water.',1,'2026-08-25 17:48:07'),(46,'BD-2000-0003','DOC-1007','Understood Doctor. Should I strictly restrict dietary salt, and are 30-minute morning brisk walks safe?',1,'2026-08-25 18:33:07'),(47,'DOC-1007','BD-2000-0003','Keep sodium under 2g daily. Moderate walks are safe and strongly encouraged. If systolic drops below 100 mmHg, message me immediately.',1,'2026-08-25 19:18:07'),(48,'BD-2000-0003','DOC-1008','Doctor, my fasting blood glucose was 7.8 mmol/L and 2-hour post-meal was 11.2 mmol/L. I am taking Metformin 500mg twice daily.',1,'2026-08-22 17:03:07'),(49,'DOC-1008','BD-2000-0003','Thank you for tracking. Since post-prandial remains above our 8.5 target, ensure you take Metformin with meals and minimize refined carbohydrates in your evening diet.',1,'2026-08-22 17:48:07'),(50,'BD-2000-0003','DOC-1008','Should I schedule an HbA1c and kidney function test before our upcoming clinic review?',1,'2026-08-22 18:33:07'),(51,'DOC-1008','BD-2000-0003','Yes, please complete an HbA1c and serum creatinine test next week, then upload the PDF report directly to your xMED vault.',1,'2026-08-22 19:18:07'),(52,'BD-2000-0003','DOC-1008','Will do Doctor, uploaded last month’s lipid panel as well.',0,'2026-08-22 20:03:07'),(53,'BD-2000-0003','DOC-1009','Hello Doctor, I developed a sudden fever of 102°F yesterday with retro-orbital eye pain and severe body ache. Could this be dengue?',1,'2026-08-19 17:03:07'),(54,'DOC-1009','BD-2000-0003','Given seasonal trends, do NOT take any Ibuprofen or Aspirin. Take only Paracetamol 500mg up to every 6 hours and drink plenty of ORS and coconut water.',1,'2026-08-19 17:48:07'),(55,'BD-2000-0003','DOC-1009','Should I get a Complete Blood Count (CBC) and Dengue NS1 antigen test done today?',1,'2026-08-19 18:33:07'),(56,'DOC-1009','BD-2000-0003','Yes, get a CBC and NS1 antigen test today. If platelets drop below 100,000 or you notice severe abdominal pain, proceed to the hospital emergency triage.',1,'2026-08-19 19:18:07'),(57,'BD-2000-0003','DOC-1010','Dr. Kabir, I have severe burning in my upper chest at night, despite taking Omeprazole 20mg daily.',1,'2026-08-16 17:03:07'),(58,'DOC-1010','BD-2000-0003','Make sure you take Omeprazole 30 minutes before breakfast on an empty stomach. Avoid spicy dinners and do not lie flat within 2 hours of eating.',1,'2026-08-16 17:48:07'),(59,'BD-2000-0003','DOC-1010','Can I take a chewable antacid if nighttime burning wakes me up?',1,'2026-08-16 18:33:07'),(60,'DOC-1010','BD-2000-0003','Yes, an aluminum-magnesium hydroxide chewable antacid can be taken for breakthrough nocturnal acidity.',1,'2026-08-16 19:18:07'),(61,'BD-2000-0003','DOC-1010','Thank you Doctor, adjusting my meal schedule tonight.',1,'2026-08-16 20:03:07'),(62,'DOC-1010','BD-2000-0003','You are welcome. Keep a symptom diary for the next 7 days.',1,'2026-08-16 20:48:07'),(63,'BD-2000-0003','DOC-1011','Doctor, my child has been coughing persistently at night and has a faint wheezing sound during running.',1,'2026-08-26 17:03:07'),(64,'DOC-1011','BD-2000-0003','This suggests reactive airway bronchospasm. Please administer the Salbutamol 100mcg inhaler with a spacer: 2 puffs as directed.',1,'2026-08-26 17:48:07'),(65,'BD-2000-0003','DOC-1011','How frequently can we repeat the inhaler puffs if coughing persists?',1,'2026-08-26 18:33:07'),(66,'DOC-1011','BD-2000-0003','You can repeat 2 puffs after 20 minutes once. If chest indrawing or breathlessness appears, visit our emergency center immediately.',0,'2026-08-26 19:18:07'),(67,'BD-2000-0004','DOC-1010','Hello Doctor, the red itchy rash on my forearms has flared up after using synthetic laundry powder.',1,'2026-08-18 17:04:07'),(68,'DOC-1010','BD-2000-0004','Apply the Hydrocortisone cream thinly twice daily for 5 days only, followed by liberal amounts of plain petroleum jelly.',1,'2026-08-18 17:49:07'),(69,'BD-2000-0004','DOC-1010','Can I take an antihistamine like Cetirizine 10mg at night for the itching?',1,'2026-08-18 18:34:07'),(70,'DOC-1010','BD-2000-0004','Yes, Cetirizine 10mg at bedtime will relieve nighttime itching and help you rest without scratching.',0,'2026-08-18 19:19:07'),(71,'BD-2000-0004','DOC-1011','Good afternoon Doctor, my abdominal surgical incision looks slightly pink, but there is no fever or pus.',1,'2026-08-15 17:04:07'),(72,'DOC-1011','BD-2000-0004','Mild pink erythema is normal during surgical wound remodeling. Keep the area completely dry and clean with sterile dressing.',1,'2026-08-15 17:49:07'),(73,'BD-2000-0004','DOC-1011','When should I visit the outpatient clinic for suture removal?',1,'2026-08-15 18:34:07'),(74,'DOC-1011','BD-2000-0004','Please visit the surgical OPD this Thursday between 9 AM and 1 PM for stitch removal and scar assessment.',1,'2026-08-15 19:19:07'),(75,'BD-2000-0004','DOC-1012','Doctor, my fasting lipid profile shows LDL 155 mg/dL. I have started Atorvastatin 10mg nightly.',1,'2026-08-25 17:04:07'),(76,'DOC-1012','BD-2000-0004','Atorvastatin works best when taken at bedtime to target peak hepatic cholesterol synthesis. Continue taking it nightly.',1,'2026-08-25 17:49:07'),(77,'BD-2000-0004','DOC-1012','Should I be concerned about muscle soreness or liver enzymes?',1,'2026-08-25 18:34:07'),(78,'DOC-1012','BD-2000-0004','Mild fatigue is rare, but report any severe unexplained muscle cramps. We will recheck liver enzymes and lipid levels in 8 weeks.',1,'2026-08-25 19:19:07'),(79,'BD-2000-0004','DOC-1013','Dr. Tanvir, I get throbbing one-sided headaches preceded by bright zigzag lines in my visual field.',1,'2026-08-22 17:04:07'),(80,'DOC-1013','BD-2000-0004','These are classic migraine episodes with aura. Take Naproxen 500mg immediately when the visual aura begins, before the pain peaks.',1,'2026-08-22 17:49:07'),(81,'BD-2000-0004','DOC-1013','Should I avoid specific dietary triggers like aged cheese or caffeine?',1,'2026-08-22 18:34:07'),(82,'DOC-1013','BD-2000-0004','Yes, maintain a regular sleep schedule, stay hydrated, and note down food triggers in your daily health journal.',0,'2026-08-22 19:19:07'),(83,'BD-2000-0004','DOC-1014','Doctor, my TSH is 5.8 mIU/L on Levothyroxine 50mcg. I still feel unusually cold and sluggish in the morning.',1,'2026-08-19 17:04:07'),(84,'DOC-1014','BD-2000-0004','Your dose requires a slight adjustment. Increase Levothyroxine to 75mcg daily, taken with plain water 45 minutes before breakfast.',1,'2026-08-19 17:49:07'),(85,'BD-2000-0004','DOC-1014','Can I take my calcium and vitamin D tablets together with the thyroid pill?',1,'2026-08-19 18:34:07'),(86,'DOC-1014','BD-2000-0004','No, calcium binds to thyroxine and blocks absorption. Separate calcium supplements by at least 4 hours.',1,'2026-08-19 19:19:07'),(87,'BD-2000-0005','DOC-1013','Good morning Doctor, I have been taking Amlodipine 5mg for 4 days as prescribed, but feel slightly lightheaded around noon. Should I adjust the timing?',1,'2026-08-24 17:05:07'),(88,'DOC-1013','BD-2000-0005','Hello! Mild lightheadedness can happen initially as peripheral vascular resistance drops. Please check your blood pressure at noon and take the tablet right after breakfast with a glass of water.',1,'2026-08-24 17:50:07'),(89,'BD-2000-0005','DOC-1013','Understood Doctor. Should I strictly restrict dietary salt, and are 30-minute morning brisk walks safe?',1,'2026-08-24 18:35:07'),(90,'DOC-1013','BD-2000-0005','Keep sodium under 2g daily. Moderate walks are safe and strongly encouraged. If systolic drops below 100 mmHg, message me immediately.',1,'2026-08-24 19:20:07'),(91,'BD-2000-0005','DOC-1014','Doctor, my fasting blood glucose was 7.8 mmol/L and 2-hour post-meal was 11.2 mmol/L. I am taking Metformin 500mg twice daily.',1,'2026-08-21 17:05:07'),(92,'DOC-1014','BD-2000-0005','Thank you for tracking. Since post-prandial remains above our 8.5 target, ensure you take Metformin with meals and minimize refined carbohydrates in your evening diet.',1,'2026-08-21 17:50:07'),(93,'BD-2000-0005','DOC-1014','Should I schedule an HbA1c and kidney function test before our upcoming clinic review?',1,'2026-08-21 18:35:07'),(94,'DOC-1014','BD-2000-0005','Yes, please complete an HbA1c and serum creatinine test next week, then upload the PDF report directly to your xMED vault.',1,'2026-08-21 19:20:07'),(95,'BD-2000-0005','DOC-1014','Will do Doctor, uploaded last month’s lipid panel as well.',1,'2026-08-21 20:05:07'),(96,'BD-2000-0005','DOC-1015','Hello Doctor, I developed a sudden fever of 102°F yesterday with retro-orbital eye pain and severe body ache. Could this be dengue?',1,'2026-08-18 17:05:07'),(97,'DOC-1015','BD-2000-0005','Given seasonal trends, do NOT take any Ibuprofen or Aspirin. Take only Paracetamol 500mg up to every 6 hours and drink plenty of ORS and coconut water.',1,'2026-08-18 17:50:07'),(98,'BD-2000-0005','DOC-1015','Should I get a Complete Blood Count (CBC) and Dengue NS1 antigen test done today?',1,'2026-08-18 18:35:07'),(99,'DOC-1015','BD-2000-0005','Yes, get a CBC and NS1 antigen test today. If platelets drop below 100,000 or you notice severe abdominal pain, proceed to the hospital emergency triage.',0,'2026-08-18 19:20:07'),(100,'BD-2000-0005','DOC-1016','Dr. Kabir, I have severe burning in my upper chest at night, despite taking Omeprazole 20mg daily.',1,'2026-08-15 17:05:07'),(101,'DOC-1016','BD-2000-0005','Make sure you take Omeprazole 30 minutes before breakfast on an empty stomach. Avoid spicy dinners and do not lie flat within 2 hours of eating.',1,'2026-08-15 17:50:07'),(102,'BD-2000-0005','DOC-1016','Can I take a chewable antacid if nighttime burning wakes me up?',1,'2026-08-15 18:35:07'),(103,'DOC-1016','BD-2000-0005','Yes, an aluminum-magnesium hydroxide chewable antacid can be taken for breakthrough nocturnal acidity.',1,'2026-08-15 19:20:07'),(104,'BD-2000-0005','DOC-1016','Thank you Doctor, adjusting my meal schedule tonight.',1,'2026-08-15 20:05:07'),(105,'DOC-1016','BD-2000-0005','You are welcome. Keep a symptom diary for the next 7 days.',1,'2026-08-15 20:50:07'),(106,'BD-2000-0005','DOC-1017','Doctor, my child has been coughing persistently at night and has a faint wheezing sound during running.',1,'2026-08-25 17:05:07'),(107,'DOC-1017','BD-2000-0005','This suggests reactive airway bronchospasm. Please administer the Salbutamol 100mcg inhaler with a spacer: 2 puffs as directed.',1,'2026-08-25 17:50:07'),(108,'BD-2000-0005','DOC-1017','How frequently can we repeat the inhaler puffs if coughing persists?',1,'2026-08-25 18:35:07'),(109,'DOC-1017','BD-2000-0005','You can repeat 2 puffs after 20 minutes once. If chest indrawing or breathlessness appears, visit our emergency center immediately.',1,'2026-08-25 19:20:07'),(110,'BD-2000-0006','DOC-1016','Hello Doctor, the red itchy rash on my forearms has flared up after using synthetic laundry powder.',1,'2026-08-17 17:06:07'),(111,'DOC-1016','BD-2000-0006','Apply the Hydrocortisone cream thinly twice daily for 5 days only, followed by liberal amounts of plain petroleum jelly.',1,'2026-08-17 17:51:07'),(112,'BD-2000-0006','DOC-1016','Can I take an antihistamine like Cetirizine 10mg at night for the itching?',1,'2026-08-17 18:36:07'),(113,'DOC-1016','BD-2000-0006','Yes, Cetirizine 10mg at bedtime will relieve nighttime itching and help you rest without scratching.',1,'2026-08-17 19:21:07'),(114,'BD-2000-0006','DOC-1017','Good afternoon Doctor, my abdominal surgical incision looks slightly pink, but there is no fever or pus.',1,'2026-08-14 17:06:07'),(115,'DOC-1017','BD-2000-0006','Mild pink erythema is normal during surgical wound remodeling. Keep the area completely dry and clean with sterile dressing.',1,'2026-08-14 17:51:07'),(116,'BD-2000-0006','DOC-1017','When should I visit the outpatient clinic for suture removal?',1,'2026-08-14 18:36:07'),(117,'DOC-1017','BD-2000-0006','Please visit the surgical OPD this Thursday between 9 AM and 1 PM for stitch removal and scar assessment.',0,'2026-08-14 19:21:07'),(118,'BD-2000-0006','DOC-1018','Doctor, my fasting lipid profile shows LDL 155 mg/dL. I have started Atorvastatin 10mg nightly.',1,'2026-08-24 17:06:07'),(119,'DOC-1018','BD-2000-0006','Atorvastatin works best when taken at bedtime to target peak hepatic cholesterol synthesis. Continue taking it nightly.',1,'2026-08-24 17:51:07'),(120,'BD-2000-0006','DOC-1018','Should I be concerned about muscle soreness or liver enzymes?',1,'2026-08-24 18:36:07'),(121,'DOC-1018','BD-2000-0006','Mild fatigue is rare, but report any severe unexplained muscle cramps. We will recheck liver enzymes and lipid levels in 8 weeks.',1,'2026-08-24 19:21:07'),(122,'BD-2000-0006','DOC-1019','Dr. Tanvir, I get throbbing one-sided headaches preceded by bright zigzag lines in my visual field.',1,'2026-08-21 17:06:07'),(123,'DOC-1019','BD-2000-0006','These are classic migraine episodes with aura. Take Naproxen 500mg immediately when the visual aura begins, before the pain peaks.',1,'2026-08-21 17:51:07'),(124,'BD-2000-0006','DOC-1019','Should I avoid specific dietary triggers like aged cheese or caffeine?',1,'2026-08-21 18:36:07'),(125,'DOC-1019','BD-2000-0006','Yes, maintain a regular sleep schedule, stay hydrated, and note down food triggers in your daily health journal.',1,'2026-08-21 19:21:07'),(126,'BD-2000-0006','DOC-1020','Doctor, my TSH is 5.8 mIU/L on Levothyroxine 50mcg. I still feel unusually cold and sluggish in the morning.',1,'2026-08-18 17:06:07'),(127,'DOC-1020','BD-2000-0006','Your dose requires a slight adjustment. Increase Levothyroxine to 75mcg daily, taken with plain water 45 minutes before breakfast.',1,'2026-08-18 17:51:07'),(128,'BD-2000-0006','DOC-1020','Can I take my calcium and vitamin D tablets together with the thyroid pill?',1,'2026-08-18 18:36:07'),(129,'DOC-1020','BD-2000-0006','No, calcium binds to thyroxine and blocks absorption. Separate calcium supplements by at least 4 hours.',0,'2026-08-18 19:21:07'),(130,'BD-2000-0007','DOC-1019','Good morning Doctor, I have been taking Amlodipine 5mg for 4 days as prescribed, but feel slightly lightheaded around noon. Should I adjust the timing?',1,'2026-08-23 17:07:07'),(131,'DOC-1019','BD-2000-0007','Hello! Mild lightheadedness can happen initially as peripheral vascular resistance drops. Please check your blood pressure at noon and take the tablet right after breakfast with a glass of water.',1,'2026-08-23 17:52:07'),(132,'BD-2000-0007','DOC-1019','Understood Doctor. Should I strictly restrict dietary salt, and are 30-minute morning brisk walks safe