/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_update_medicine_usage
      AFTER INSERT ON prescription_items
      FOR EACH ROW
      BEGIN
        UPDATE medicines 
        SET total_prescribed_count = total_prescribed_count + 1 
        WHERE medicine_id = NEW.medicine_id;
      END */;;
