/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_audit_prescriptions
      AFTER INSERT ON prescriptions
      FOR EACH ROW
      BEGIN
        INSERT INTO prescription_audit_logs (
          prescription_id, action_type, performed_by_doctor_id, new_data
        ) VALUES (
          NEW.prescription_id,
          'INSERT',
          NEW.doctor_id,
          CONCAT('Diagnosis: ', NEW.diagnosis, ', Notes: ', IFNULL(NEW.clinical_notes, 'None'))
        );
      END */;;
DELIMITER ;
